# Mocking the external functions
def mock_check_if_file_exists(file_path):
    return True


def mock_multiprocess_dispatch(*args, **kwargs):
    return [pd.DataFrame({"test": [1, 2, 3]})]


def mock_execute_command(cmd):
    return True


class TestsmBGCLocalRunner(unittest.TestCase):
    @patch("pathlib.Path.glob", return_value=[Path("test_genome.fasta")])
    def test_init(self, mock_glob):
        # Test the initialization of smBGCLocalRunner
        runner = smbgc.smBGCLocalRunner(
            genome_fasta_dir=Path("/genomes"),
            out_dir=Path("/output"),
            strictness="relaxed",
            genefinding_tool="prodigal",
            database_dir=Path("/databases"),
            cores=4,
            available_cores=8,
            concurrent=True,
            debug=True,
        )
        self.assertEqual(runner.genome_fasta_dir, Path("/genomes"))
        self.assertEqual(
            runner.antismash_raw_results_dir,
            Path("/output/smBGC/antismash_raw_results"),
        )
        self.assertEqual(runner.cores, 4)
        self.assertEqual(runner.strictness, "relaxed")
        self.assertEqual(runner.genefinding_tool, "prodigal")
        self.assertEqual(runner.database_dir, Path("/databases"))
        self.assertEqual(runner.debug, True)
        self.assertEqual(len(runner.genome_files), 1)
        self.assertEqual(
            runner.concurrent_jobs, 1
        )  # Assuming mock for calc_avail_dispatchers returns 1

    def test_create_antismash_cmd(self):
        # Test the command generation
        runner = smbgc.smBGCLocalRunner(
            genome_fasta_dir=Path("/genomes"),
            out_dir=Path("/output"),
            strictness="relaxed",
            genefinding_tool="prodigal",
            database_dir=None,
            cores=4,
            available_cores=8,
            concurrent=True,
            debug=True,
        )
        cmd = runner.create_antismash_cmd(Path("genome.fasta"), Path("/output/genome"))
        expected_cmd = (
            "antismash --output-dir /output/genome --cpu 4 --hmmdetection-strictness relaxed "
            "--genefinding-tool prodigal --cb-knownclusters /genome.fasta -v -d"
        )
        self.assertEqual(cmd, expected_cmd)

    @patch("pathlib.Path.mkdir")
    @patch("unittest.mock.MagicMock")
    @patch("context.smbgc.smBGCLocalRunner.create_antismash_cmd")
    @patch("context.utils.multiprocess_dispatch")
    def test_analyze_genomes(self, mock_dispatch, mock_create_cmd, mock_mkdir):
        # Test the analyze_genomes function
        runner = smbgc.smBGCLocalRunner(
            genome_fasta_dir=Path("/genomes"),
            out_dir=Path("/output"),
            strictness="relaxed",
            genefinding_tool="prodigal",
            database_dir=None,
            cores=4,
            available_cores=8,
            concurrent=True,
            debug=False,
        )
        mock_create_cmd.return_value = "fake_cmd"

        runner.analyze_genomes()

        self.assertEqual(mock_mkdir.call_count, len(runner.genome_files))
        mock_dispatch.assert_called_once()


class TestsmBGCParser(unittest.TestCase):
    def setUp(self):
        self.parser = smbgc.smBGCParser(out_dir=Path("/output"), cores=4)

    @patch("builtins.open", new_callable=mock_open, read_data='{"test": "data"}')
    def test_load_json(self, mock_file):
        # Test the JSON loading function
        result = self.parser.load_json("test.json")
        self.assertEqual(result, {"test": "data"})

    def test_has_identified_smbgcs(self):
        # Test the check for identified smBGCs
        self.assertTrue(self.parser.has_identified_smbgcs([1, 2, 3]))
        self.assertFalse(self.parser.has_identified_smbgcs([]))

    @patch(
        "context.smbgc.smBGCParser.load_json",
        return_value={
            "records": [
                {
                    "areas": [{"start": 100, "end": 200, "products": ["product1"]}],
                    "id": "region_1",
                    "modules": {
                        "antismash.modules.clusterblast": {
                            "knowncluster": {
                                "results": [
                                    {"ranking": [[{"proteins": [1, 2]}, {"hits": 2}]]}
                                ]
                            }
                        }
                    },
                }
            ]
        },
    )
    @patch("context.smbgc.smBGCParser.has_identified_smbgcs", return_value=True)
    @patch("context.utils.check_if_file_exists", side_effect=mock_check_if_file_exists)
    def test_parse_strain_results_empty(
        self, mock_exists, mock_has_smbgcs, mock_load_json
    ):
        # Test parsing a strain's results into a DataFrame
        result_df = self.parser.parse_strain_results(Path("/output/smBGC/strain_1"))
        self.assertTrue(result_df.empty)
        # self.assertEqual(len(result_df), 1)
        # self.assertEqual(result_df.iloc[0]["Genome"], "strain_1")

    # def test_parse_strain_results_with_data(
    #     self, mock_exists, mock_has_smbgcs, mock_load_json
    # ):
